INSERT INTO `term_conditions` (`id`, `version`, `content`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'v2026.03.02-26', 'Syarat & Ketentuan Tata Tertib Ujian Online\nHarap baca dengan teliti sebelum memulai ujian. Dengan menekan tombol \"Setuju/Mulai Ujian\", Anda dianggap telah memahami dan berkomitmen untuk mematuhi peraturan di bawah ini:\n\n1. Integritas Akademik & Larangan Kecurangan\nPeserta dilarang keras melakukan tindakan kecurangan dalam bentuk apa pun, termasuk namun tidak terbatas pada:\n\nPlagiarisme: Menyontek jawaban dari internet, buku, atau catatan fisik/digital.\n\nBantuan Pihak Ketiga: Berkomunikasi dengan orang lain, baik secara langsung maupun melalui aplikasi pesan (WhatsApp, Telegram, dll) selama ujian berlangsung.\n\nJoki Ujian: Mengizinkan orang lain mengerjakan ujian atas nama Anda.\n\n2. Pengawasan Sistem (Anti-Cheating Measures)\nSistem ujian ini dilengkapi dengan fitur deteksi kecurangan otomatis. Peserta dilarang:\n\nPindah Tab/Jendela (Tab Switching): Sistem akan mencatat setiap kali Anda keluar dari halaman ujian. Pelanggaran batas maksimal pindah tab akan mengakibatkan ujian terhenti secara otomatis.\n\nSplit Screen & Dual Monitor: Dilarang menggunakan dua layar atau membagi layar browser.\n\nScreen Sharing & Recording: Dilarang melakukan tangkapan layar (screenshot) atau merekam soal ujian.\n\n3. Ketentuan Teknis & Perangkat\nKoneksi Stabil: Peserta wajib memastikan koneksi internet stabil. Gangguan koneksi akibat kelalaian pribadi bukan tanggung jawab penyelenggara.\n\nIzin Akses: Peserta wajib memberikan izin akses pada kamera (jika fitur proctoring aktif) dan lokasi jika diminta oleh sistem.\n\nSatu Perangkat: Ujian hanya boleh diakses melalui satu perangkat resmi yang telah terdaftar.\n\n4. Sanksi Pelanggaran\nSetiap aktivitas mencurigakan yang terdeteksi oleh sistem akan dicatat sebagai Log Pelanggaran. Sanksi dapat berupa:\n\nPeringatan otomatis pada layar.\n\nPengurangan nilai secara otomatis.\n\nPembatalan status ujian (Diskualifikasi) jika terbukti melakukan pelanggaran berat.', 1, '2026-03-02 07:12:22', '2026-03-02 07:12:22');

